"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface Dice5IconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface Dice5IconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const Dice5Icon = forwardRef<Dice5IconHandle, Dice5IconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const rollVariants: Variants = {
   normal: { rotate: 0, y: 0, scale: 1, transition: { duration: 0 } },
   animate: {
    rotate: [0, 180],
    y: [0, -3, 0],
    scale: [1, 0.85, 1],
    transition: { duration: 0.7 * duration, ease: "easeInOut" },
   },
  };

  const pipVariants: Variants = {
   normal: { scale: 1 },
   animate: (i: number) => ({
    scale: [1, 0, 1.5, 1],
    transition: {
     duration: 0.35 * duration,
     ease: "easeOut",
     times: [0, 0.2, 0.6, 1],
     delay: (0.55 + i * 0.05) * duration,
    },
   }),
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.g
       variants={rollVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
      >
       <rect width="18" height="18" x="3" y="3" rx="2" ry="2" />
       <m.path
        d="M16 8h.01"
        variants={pipVariants}
        custom={1}
        style={{ transformBox: "view-box", originX: "16px", originY: "8px" }}
       />
       <m.path
        d="M8 8h.01"
        variants={pipVariants}
        custom={2}
        style={{ transformBox: "view-box", originX: "8px", originY: "8px" }}
       />
       <m.path
        d="M8 16h.01"
        variants={pipVariants}
        custom={3}
        style={{ transformBox: "view-box", originX: "8px", originY: "16px" }}
       />
       <m.path
        d="M16 16h.01"
        variants={pipVariants}
        custom={4}
        style={{ transformBox: "view-box", originX: "16px", originY: "16px" }}
       />
       <m.path
        d="M12 12h.01"
        variants={pipVariants}
        custom={0}
        style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
       />
      </m.g>
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

Dice5Icon.displayName = "Dice5Icon";
export { Dice5Icon };
